import{createHash as H,randomBytes as R}from"node:crypto";import{createRequire as Q}from"node:module";const L=m=>console.log("[railway-bootstrap] "+m),P=process.env.PORT||"3100",U=(process.env.PAPERCLIP_PUBLIC_URL||"http://localhost:"+P).replace(/\/+$/,""),D=process.env.DATABASE_URL,E=Math.max(1,Math.min(720,Number(process.env.PAPERCLIP_BOOTSTRAP_INVITE_HOURS)||72));async function W(){const t=Date.now();while(Date.now()-t<9e5){try{const r=await fetch("http://127.0.0.1:"+P+"/api/health",{signal:AbortSignal.timeout(5e3)});if(r.ok){const b=await r.json();if(b&&b.status==="ok"&&b.bootstrapStatus)return b}}catch{}await new Promise(r=>setTimeout(r,3e3))}return null}async function M(){if(!D)return L("DATABASE_URL not set; skipping first-admin invite");const h=await W();if(!h)return L("server not healthy in time; skipping first-admin invite");if(h.deploymentMode!=="authenticated")return;if(h.bootstrapStatus!=="bootstrap_pending")return L("instance already has an admin; no invite needed");const sql=Q("/app/packages/db/package.json")("postgres")(D,{max:1,onnotice:()=>{}});try{const[{c}]=await sql`SELECT count(*)::int AS c FROM instance_user_roles WHERE role='instance_admin'`;if(c>0)return;const n=new Date();await sql`UPDATE invites SET revoked_at=${n},updated_at=${n} WHERE invite_type='bootstrap_ceo' AND revoked_at IS NULL AND accepted_at IS NULL AND expires_at>${n}`;const k="pcp_bootstrap_"+R(24).toString("hex"),x=new Date(Date.now()+E*36e5);await sql`INSERT INTO invites(invite_type,token_hash,allowed_join_types,expires_at,invited_by_user_id)VALUES('bootstrap_ceo',${H("sha256").update(k).digest("hex")},'human',${x},'system')`;L("No Paperclip admin yet. Sign up, then open this one-time first-admin invite URL:");L(U+"/invite/"+k);L("Expires "+x.toISOString()+" (a fresh link is printed on every restart until claimed)")}finally{await sql.end({timeout:5}).catch(()=>{})}}M().catch(e=>L("could not create first-admin invite: "+(e&&e.message||e)));
